## Question:
What does this code print?

```ts
class Base {
    private _count: number = 0;
    static total: number = 0;

    constructor() {
        Base.total++;
    }

    get count(): number {
        return this._count;
    }

    set count(value: number) {
        if (value < 0) throw new Error("Negative");
        this._count = value;
    }
}

class Child extends Base {
    constructor() {
        super();
        this.count = 5;
    }
}

const a = new Base();
const b = new Child();
try {
    b.count = -1;
} catch (e) {}

console.log(a.count, b.count, Base.total);
```
